-- 961-Dev: Seed the two Developer 2 guided journeys and their assessments.
-- No existing data or learner progress is overwritten.
BEGIN;
DO $seed$
DECLARE
  p jsonb;
  lev jsonb;
  mis jsonb;
  t jsonb;
  question jsonb;
  answer text;
  pr_id bigint;
  lev_id bigint;
  mis_id bigint;
  assess_id bigint;
  question_id bigint;
  n integer;
  count_levels integer;
  count_missions integer;
  count_tasks integer;
BEGIN
  FOR p IN SELECT value FROM jsonb_array_elements($guided_seed$[{"slug": "quiz-application", "levels": [{"number": 1, "name": "Project Setup & HTML Structure", "goal": "Build the complete HTML structure of the quiz application.", "given": ["Create index.html, styles.css, and script.js in one folder.", "Use semantic HTML elements.", "Learn how to connect HTML, CSS, and JavaScript."]}, {"number": 2, "name": "CSS Styling & Responsive Design", "goal": "Create a modern, accessible, responsive quiz interface.", "given": ["Keep the HTML structure from Level 1.", "Use CSS variables, Flexbox, and Grid.", "Test the interface on desktop and mobile."]}, {"number": 3, "name": "JavaScript & Quiz Logic", "goal": "Display questions dynamically and handle answer selection.", "given": ["Use JavaScript arrays and objects.", "Use DOM manipulation and event listeners.", "Keep the HTML and CSS from previous levels."]}, {"number": 4, "name": "Score & Quiz Navigation", "goal": "Calculate scores and navigate between questions.", "given": ["Use conditions, functions, and state variables.", "Prevent answering the same question twice.", "Update the question counter and progress bar."]}, {"number": 5, "name": "Final Results & Testing", "goal": "Complete, restart, and test the quiz application.", "given": ["Display the final score.", "Reset the quiz without refreshing the page.", "Test correct answers, incorrect answers, and mobile layouts."]}], "missions": [{"number": 1, "level": 1, "levelTitle": "Project Setup & HTML Structure", "title": "Set up the project files", "why": "Organizing your files correctly creates a foundation for a maintainable web application.", "workIn": "Create index.html, styles.css, and script.js in the same folder.", "tasks": ["Create a folder named quiz-application.", "Create the three required files.", "Write a valid HTML5 document.", "Add the UTF-8 charset and viewport metadata.", "Connect styles.css and script.js.", "Open index.html in your browser."], "completedWhen": "The browser opens the HTML document and displays the Developer Quiz page title.", "hint1": "The head contains page information and links to external files.", "hint2": "Use a link element for CSS and a script element with defer for JavaScript.", "solutionLanguage": "html", "solution": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\"\n        content=\"width=device-width, initial-scale=1.0\">\n  <title>Developer Quiz</title>\n  <link rel=\"stylesheet\" href=\"styles.css\">\n  <script src=\"script.js\" defer></script>\n</head>\n<body>\n  <main class=\"quiz-container\">\n    <h1>Developer Quiz</h1>\n  </main>\n</body>\n</html>", "check": "The browser displays Developer Quiz without errors.", "image": null}, {"number": 2, "level": 1, "levelTitle": "Project Setup & HTML Structure", "title": "Build the quiz interface", "why": "The interface needs dedicated elements for questions, answers, feedback, and navigation.", "workIn": "index.html. Replace the existing main element with the following structure.", "tasks": ["Create the quiz header.", "Add question and score counters.", "Add a progress bar.", "Create a question heading.", "Create an answer container.", "Add feedback and navigation elements.", "Create a hidden results section."], "completedWhen": "The page contains all the elements required by the future JavaScript logic.", "hint1": "Give dynamic elements unique IDs so JavaScript can select them.", "hint2": "Use question, answers, score, progress, and next-button as element IDs.", "solutionLanguage": "html", "solution": "<main class=\"quiz-container\">\n  <header class=\"quiz-header\">\n    <p class=\"eyebrow\">WEB DEVELOPMENT</p>\n    <h1>Developer Quiz</h1>\n  </header>\n\n  <section id=\"quiz-screen\">\n    <div class=\"quiz-info\">\n      <span id=\"question-counter\">\n        Question 1 of 5\n      </span>\n      <span>Score: <strong id=\"score\">0</strong></span>\n    </div>\n\n    <div class=\"progress-track\">\n      <div id=\"progress\"></div>\n    </div>\n\n    <h2 id=\"question\">\n      Which language adds interactivity to websites?\n    </h2>\n\n    <div id=\"answers\">\n      <button class=\"answer\">HTML</button>\n      <button class=\"answer\">CSS</button>\n      <button class=\"answer\">JavaScript</button>\n      <button class=\"answer\">SQL</button>\n    </div>\n\n    <p id=\"feedback\" aria-live=\"polite\"></p>\n\n    <button id=\"next-button\" disabled>\n      Next Question\n    </button>\n  </section>\n\n  <section id=\"result-screen\" hidden>\n    <h2>Quiz Completed!</h2>\n    <p id=\"final-score\"></p>\n    <button id=\"restart-button\">\n      Restart Quiz\n    </button>\n  </section>\n</main>", "check": "The heading, four answer buttons, score, progress bar, and Next Question button appear.", "image": "/projects/quiz-application/mission-02.png"}, {"number": 3, "level": 2, "levelTitle": "CSS Styling & Responsive Design", "title": "Style the quiz container", "why": "A consistent visual foundation makes the application readable and professional.", "workIn": "styles.css. Add the initial global styles.", "tasks": ["Define reusable CSS color variables.", "Remove the default body margin.", "Center the quiz on the page.", "Style the main quiz container.", "Style the heading and score information.", "Create a visible progress bar."], "completedWhen": "The quiz appears as a centered card with consistent colors, spacing, and typography.", "hint1": "Use CSS custom properties inside :root.", "hint2": "Use display: grid and place-items: center on the body.", "solutionLanguage": "css", "solution": ":root {\n  --blue: #0066ff;\n  --cyan: #22d3ee;\n  --background: #080d1e;\n  --surface: #151d34;\n  --border: #334155;\n  --text: #ffffff;\n  --muted: #94a3b8;\n  --success: #22c55e;\n  --error: #ef4444;\n}\n\n* {\n  box-sizing: border-box;\n}\n\n[hidden] {\n  display: none !important;\n}\n\nbody {\n  margin: 0;\n  min-height: 100vh;\n  padding: 24px;\n  display: grid;\n  place-items: center;\n  background: var(--background);\n  color: var(--text);\n  font-family: Arial, sans-serif;\n}\n\n.quiz-container {\n  width: min(100%, 620px);\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: 20px;\n  padding: 28px;\n  box-shadow: 0 15px 40px rgba(0, 0, 0, 0.2);\n}\n\n.eyebrow {\n  color: var(--cyan);\n  font-size: 12px;\n  font-weight: bold;\n  letter-spacing: 2px;\n}\n\nh1 {\n  margin: 8px 0 24px;\n}\n\n.quiz-info {\n  display: flex;\n  justify-content: space-between;\n  color: var(--muted);\n  font-size: 14px;\n}\n\n.progress-track {\n  height: 8px;\n  margin: 12px 0 24px;\n  background: var(--border);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n#progress {\n  width: 20%;\n  height: 100%;\n  background: var(--cyan);\n}", "check": "The quiz card is centered with a dark background and blue/cyan accents.", "image": null}, {"number": 4, "level": 2, "levelTitle": "CSS Styling & Responsive Design", "title": "Design answer buttons and responsive layouts", "why": "Clear buttons and responsive layouts help users interact with the quiz on different devices.", "workIn": "styles.css. Append these rules below Mission 3.", "tasks": ["Arrange answer buttons in a two-column grid.", "Style the answer buttons.", "Add hover and keyboard focus states.", "Create correct and incorrect answer styles.", "Style disabled buttons.", "Use a media query for smaller screens."], "completedWhen": "The answer buttons are readable and the layout adapts to phone screens.", "hint1": "CSS Grid can organize the answer buttons into equal columns.", "hint2": "Use grid-template-columns: repeat(2, 1fr) and a mobile media query.", "solutionLanguage": "css", "solution": "#answers {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 12px;\n  margin-top: 20px;\n}\n\nbutton {\n  font: inherit;\n  cursor: pointer;\n}\n\n.answer {\n  padding: 14px;\n  background: var(--background);\n  color: var(--text);\n  border: 1px solid var(--border);\n  border-radius: 10px;\n  text-align: left;\n}\n\n.answer:not(:disabled):hover {\n  border-color: var(--cyan);\n}\n\nbutton:focus-visible {\n  outline: 3px solid var(--cyan);\n  outline-offset: 3px;\n}\n\n.answer.correct {\n  border-color: var(--success);\n  background: #14532d;\n}\n\n.answer.incorrect {\n  border-color: var(--error);\n  background: #7f1d1d;\n}\n\n#next-button,\n#restart-button {\n  width: 100%;\n  padding: 12px;\n  border: none;\n  border-radius: 10px;\n  background: var(--blue);\n  color: white;\n  font-weight: bold;\n}\n\nbutton:disabled {\n  cursor: not-allowed;\n}\n\n#next-button:disabled {\n  opacity: 0.5;\n}\n\n#feedback {\n  min-height: 24px;\n  font-size: 14px;\n}\n\n@media (max-width: 480px) {\n  body {\n    padding: 12px;\n  }\n\n  .quiz-container {\n    padding: 18px;\n  }\n\n  #answers {\n    grid-template-columns: 1fr;\n  }\n\n  h2 {\n    font-size: 18px;\n  }\n}", "check": "Answers appear in two columns on desktop and one column on mobile.", "image": "/projects/quiz-application/mission-04.png"}, {"number": 5, "level": 3, "levelTitle": "JavaScript & Quiz Logic", "title": "Create the questions array", "why": "Storing questions as objects separates application data from presentation and makes the quiz easier to maintain.", "workIn": "script.js. Add the questions array.", "tasks": ["Create an array named questions.", "Represent every question as an object.", "Add a question property.", "Add an options array containing four answers.", "Store the correct answer index.", "Create five web development questions."], "completedWhen": "The questions array contains five valid question objects.", "hint1": "An array can store multiple objects with the same structure.", "hint2": "Array indexes start at zero. The third option has index 2.", "solutionLanguage": "javascript", "solution": "const questions = [\n  {\n    question: \"Which language adds interactivity to websites?\",\n    options: [\"HTML\", \"CSS\", \"JavaScript\", \"SQL\"],\n    correct: 2\n  },\n  {\n    question: \"Which HTML element creates a hyperlink?\",\n    options: [\"<p>\", \"<a>\", \"<div>\", \"<h1>\"],\n    correct: 1\n  },\n  {\n    question: \"Which CSS property changes text color?\",\n    options: [\"background\", \"font-size\", \"margin\", \"color\"],\n    correct: 3\n  },\n  {\n    question: \"Which method selects an element by its ID?\",\n    options: [\n      \"getElementById()\",\n      \"push()\",\n      \"split()\",\n      \"parseInt()\"\n    ],\n    correct: 0\n  },\n  {\n    question: \"What is the index of the first array element?\",\n    options: [\"1\", \"2\", \"0\", \"-1\"],\n    correct: 2\n  }\n];", "check": "Typing questions.length in the browser console returns 5.", "image": null}, {"number": 6, "level": 3, "levelTitle": "JavaScript & Quiz Logic", "title": "Display questions dynamically", "why": "Dynamic rendering allows one interface to display multiple questions without creating separate HTML pages.", "workIn": "script.js. Append the following code below the questions array.", "tasks": ["Create a current question index.", "Select the question and answer elements.", "Create a function named showQuestion.", "Read the current question from the array.", "Clear previously displayed answers.", "Generate answer buttons dynamically.", "Call showQuestion when the page loads."], "completedWhen": "The first question and its four answers are generated from the JavaScript array.", "hint1": "Use questions[currentQuestion] to access the current object.", "hint2": "Use forEach and document.createElement to create answer buttons.", "solutionLanguage": "javascript", "solution": "let currentQuestion = 0;\nlet score = 0;\nlet answered = false;\n\nconst questionElement =\n  document.getElementById(\"question\");\n\nconst answersElement =\n  document.getElementById(\"answers\");\n\nconst nextButton =\n  document.getElementById(\"next-button\");\n\nconst feedback =\n  document.getElementById(\"feedback\");\n\nfunction showQuestion() {\n  answered = false;\n  nextButton.disabled = true;\n  feedback.textContent = \"\";\n\n  const current = questions[currentQuestion];\n\n  questionElement.textContent = current.question;\n  answersElement.innerHTML = \"\";\n\n  current.options.forEach((option, index) => {\n    const button = document.createElement(\"button\");\n\n    button.className = \"answer\";\n    button.type = \"button\";\n    button.textContent = option;\n    button.dataset.index = index;\n\n    answersElement.appendChild(button);\n  });\n}\n\nshowQuestion();", "check": "Changing the first question in the array changes the displayed question after refresh.", "image": null}, {"number": 7, "level": 3, "levelTitle": "JavaScript & Quiz Logic", "title": "Handle answer selection", "why": "The application must respond to user clicks, validate answers, and prevent repeated submissions.", "workIn": "script.js. Append the answer selection logic below the existing code.", "tasks": ["Listen for clicks inside the answers container.", "Identify the selected answer button.", "Compare its index with the correct answer.", "Display correct or incorrect feedback.", "Highlight the correct answer.", "Disable all answers after selection.", "Enable the Next Question button."], "completedWhen": "Selecting an answer displays feedback and prevents a second answer submission.", "hint1": "Use an event listener on the answers container.", "hint2": "Compare Number(button.dataset.index) with questions[currentQuestion].correct.", "solutionLanguage": "javascript", "solution": "answersElement.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\".answer\");\n\n  if (!button || answered) return;\n\n  answered = true;\n\n  const selected = Number(button.dataset.index);\n  const correct = questions[currentQuestion].correct;\n\n  if (selected === correct) {\n    button.classList.add(\"correct\");\n    feedback.textContent = \"Correct answer!\";\n  } else {\n    button.classList.add(\"incorrect\");\n    feedback.textContent = \"Incorrect answer.\";\n  }\n\n  answersElement.querySelectorAll(\".answer\")\n    .forEach((answerButton) => {\n      answerButton.disabled = true;\n\n      if (Number(answerButton.dataset.index) === correct) {\n        answerButton.classList.add(\"correct\");\n      }\n    });\n\n  nextButton.disabled = false;\n});", "check": "Correct answers turn green, incorrect answers turn red, and repeated clicks are prevented.", "image": "/projects/quiz-application/mission-07.png"}, {"number": 8, "level": 4, "levelTitle": "Score & Quiz Navigation", "title": "Implement score calculation", "why": "A quiz needs an accurate score that increases only once for each correct answer.", "workIn": "script.js. Add updateScore before the existing answer click listener. Inside the correct-answer branch, call updateScore().", "tasks": ["Select the score element.", "Create an updateScore function.", "Increase the score for correct answers only.", "Update the visible score.", "Keep the answered guard from Mission 7.", "Test that incorrect answers do not increase the score."], "completedWhen": "The score increases exactly once when a correct answer is selected.", "hint1": "The score variable already exists from Mission 6.", "hint2": "Increment score using score += 1 and update textContent.", "solutionLanguage": "javascript", "solution": "// Add this function before the click listener.\nconst scoreElement =\n  document.getElementById(\"score\");\n\nfunction updateScore() {\n  score += 1;\n  scoreElement.textContent = score;\n}\n\n// Inside the existing correct-answer branch,\n// add the updateScore() call:\n//\n// if (selected === correct) {\n//   button.classList.add(\"correct\");\n//   feedback.textContent = \"Correct answer!\";\n//   updateScore();\n// }\n//\n// Keep the remaining listener unchanged.", "check": "Selecting a correct answer changes the score from 0 to 1. Repeated clicks do not increase it.", "image": "/projects/quiz-application/mission-08.png"}, {"number": 9, "level": 4, "levelTitle": "Score & Quiz Navigation", "title": "Add question navigation and progress", "why": "Learners need to move through the quiz and understand how many questions remain.", "workIn": "script.js. Append the navigation code. Call updateProgress() after showQuestion() when navigating or restarting.", "tasks": ["Select the question counter and progress bar.", "Create a function to update progress.", "Display the current question number.", "Listen for Next Question clicks.", "Advance the question index.", "Prevent navigation beyond the last question.", "Show the result screen after the last answer."], "completedWhen": "The learner can navigate through all five questions in order without accessing an invalid array index.", "hint1": "The displayed question number is currentQuestion + 1.", "hint2": "Compare currentQuestion + 1 with questions.length before advancing.", "solutionLanguage": "javascript", "solution": "const counterElement =\n  document.getElementById(\"question-counter\");\n\nconst progressElement =\n  document.getElementById(\"progress\");\n\nfunction updateProgress() {\n  counterElement.textContent =\n    \"Question \" + (currentQuestion + 1) +\n    \" of \" + questions.length;\n\n  progressElement.style.width =\n    ((currentQuestion + 1) / questions.length) *\n    100 + \"%\";\n\n  nextButton.textContent =\n    currentQuestion === questions.length - 1\n      ? \"Finish Quiz\"\n      : \"Next Question\";\n}\n\nnextButton.addEventListener(\"click\", () => {\n  if (!answered) return;\n\n  if (currentQuestion + 1 < questions.length) {\n    currentQuestion += 1;\n    showQuestion();\n    updateProgress();\n  } else {\n    document.getElementById(\"quiz-screen\").hidden = true;\n    document.getElementById(\"result-screen\").hidden = false;\n\n    document.getElementById(\"final-score\").textContent =\n      \"Your score: \" + score + \" / \" + questions.length;\n  }\n});\n\nupdateProgress();\n\n// Keep updateProgress() after every showQuestion()\n// call when navigating or restarting.", "check": "The question counter and progress bar update, and Finish Quiz appears on the last question.", "image": "/projects/quiz-application/mission-09.png"}, {"number": 10, "level": 5, "levelTitle": "Final Results & Testing", "title": "Display final results and restart the quiz", "why": "A complete application should provide a meaningful result and allow users to try again.", "workIn": "script.js. Append the restart logic. Keep the result display from Mission 9.", "tasks": ["Select the quiz and result sections.", "Select the restart button.", "Create a restartQuiz function.", "Reset the question index and score.", "Hide the result screen.", "Show the quiz screen again.", "Render the first question and reset progress."], "completedWhen": "The learner can complete the quiz, view the final score, and restart without refreshing.", "hint1": "Reset all state variables to their initial values.", "hint2": "Set currentQuestion and score to zero, then call showQuestion and updateProgress.", "solutionLanguage": "javascript", "solution": "const quizScreen =\n  document.getElementById(\"quiz-screen\");\n\nconst resultScreen =\n  document.getElementById(\"result-screen\");\n\nconst restartButton =\n  document.getElementById(\"restart-button\");\n\nfunction restartQuiz() {\n  currentQuestion = 0;\n  score = 0;\n  answered = false;\n\n  scoreElement.textContent = \"0\";\n\n  resultScreen.hidden = true;\n  quizScreen.hidden = false;\n\n  showQuestion();\n  updateProgress();\n}\n\nrestartButton.addEventListener(\n  \"click\",\n  restartQuiz\n);", "check": "Restart Quiz returns to Question 1 with a score of zero.", "image": "/projects/quiz-application/mission-10.png"}, {"number": 11, "level": 5, "levelTitle": "Final Results & Testing", "title": "Test and improve the application", "why": "Testing verifies that the complete application behaves correctly under different user interactions.", "workIn": "index.html, styles.css, script.js, and browser Developer Tools.", "tasks": ["Complete the quiz with all correct answers.", "Verify that the final score is 5 out of 5.", "Complete the quiz with all incorrect answers.", "Verify that the final score is 0 out of 5.", "Verify that repeated answer clicks cannot increase the score.", "Verify that Next Question is disabled before answering.", "Restart the quiz and check all initial values.", "Test the layout at mobile and desktop widths.", "Test keyboard navigation.", "Check the browser console for JavaScript errors."], "completedWhen": "The quiz runs correctly, scores accurately, restarts successfully, and remains usable on different screen sizes.", "hint1": "Test both successful and unsuccessful user interactions.", "hint2": "Use the browser console and responsive device toolbar to identify problems.", "solutionLanguage": "javascript", "solution": "// Optional development checks.\n// Run these in the browser console.\n\nconsole.assert(\n  questions.length === 5,\n  \"There should be five questions.\"\n);\n\nconsole.assert(\n  questions.every((question) =>\n    question.options.length === 4 &&\n    Number.isInteger(question.correct) &&\n    question.correct >= 0 &&\n    question.correct < question.options.length\n  ),\n  \"Every question must have four options and a valid answer index.\"\n);\n\n// Manual testing is still required:\n// 1. All correct answers: 5/5.\n// 2. All incorrect answers: 0/5.\n// 3. No repeated scoring.\n// 4. Restart resets all values.\n// 5. Mobile layout has no horizontal overflow.\n// 6. Keyboard navigation remains accessible.", "check": "All functional tests pass and no unexpected JavaScript errors appear.", "image": null}], "questions": [{"id": 1, "question": "Why do we store quiz questions in an array of objects?", "options": ["To change the background color", "To organize data and display questions dynamically", "To prevent CSS from loading", "To create a separate HTML page for every question"], "correct": 1, "explanation": "Arrays of objects organize questions, options, and correct answers in a reusable structure."}, {"id": 2, "question": "How can we prevent a user from scoring twice on the same question?", "options": ["Increase the score every time a button is clicked", "Refresh the page after every answer", "Use an answered variable and disable the answer buttons", "Remove the questions array"], "correct": 2, "explanation": "The answered variable prevents repeated submissions, while disabling buttons prevents additional selections."}, {"id": 3, "question": "What should happen when the user restarts the quiz?", "options": ["Reset the question index, score, and interface", "Keep the previous score", "Delete all questions", "Display only the last question"], "correct": 0, "explanation": "Restarting requires resetting the application state and displaying the first question again."}]}, {"slug": "ecommerce-frontend", "levels": [{"number": 1, "name": "Project Setup & HTML Structure", "goal": "Build the semantic HTML foundation of an online store.", "given": ["Create index.html, styles.css, and script.js.", "Use semantic HTML elements.", "Assign unique IDs to interactive elements."]}, {"number": 2, "name": "CSS Styling & Responsive Design", "goal": "Design a modern and responsive shopping experience.", "given": ["Keep the HTML structure from Level 1.", "Use CSS variables, Flexbox, and Grid.", "Consider desktop and mobile users."]}, {"number": 3, "name": "Dynamic Products, Search & Filtering", "goal": "Render and filter product data dynamically using JavaScript.", "given": ["Use JavaScript arrays and objects.", "Understand DOM manipulation.", "Use event listeners and array filtering."]}, {"number": 4, "name": "Shopping Cart & Price Calculation", "goal": "Build an interactive shopping cart with accurate totals.", "given": ["Maintain cart data in a JavaScript array.", "Use product IDs to identify items.", "Update the interface whenever the cart changes."]}, {"number": 5, "name": "Local Storage & Final Testing", "goal": "Persist shopping cart data and test the complete application.", "given": ["Understand JSON serialization.", "Use the browser Local Storage API.", "Test functionality, responsiveness, and accessibility."]}], "missions": [{"number": 1, "level": 1, "levelTitle": "Project Setup & HTML Structure", "title": "Set up the project files", "why": "A clean project structure separates content, styling, and application logic, making the store easier to develop and maintain.", "workIn": "Create a folder named ecommerce-frontend containing index.html, styles.css, and script.js.", "tasks": ["Create the project folder.", "Create index.html.", "Create styles.css.", "Create script.js.", "Add the HTML5 document structure.", "Connect the CSS and JavaScript files.", "Open index.html in your browser."], "completedWhen": "The browser displays the TechStore heading without errors.", "hint1": "Separate HTML structure, CSS styling, and JavaScript behavior into different files.", "hint2": "Use a link element for CSS and a script element with defer for JavaScript.", "solutionLanguage": "html", "solution": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n\n  <meta name=\"viewport\"\n        content=\"width=device-width, initial-scale=1.0\">\n\n  <title>TechStore</title>\n\n  <link rel=\"stylesheet\" href=\"styles.css\">\n  <script src=\"script.js\" defer></script>\n</head>\n\n<body>\n  <main id=\"store\">\n    <h1>TechStore</h1>\n  </main>\n</body>\n</html>", "check": "The page opens successfully and the browser tab displays TechStore.", "image": null}, {"number": 2, "level": 1, "levelTitle": "Project Setup & HTML Structure", "title": "Build the store header and navigation", "why": "The header provides the store identity, navigation links, and a clear shopping cart indicator.", "workIn": "index.html. Insert the header immediately before the existing main element.", "tasks": ["Create a semantic header.", "Display the TechStore brand.", "Create navigation links.", "Add a shopping cart button.", "Create a cart count indicator.", "Use meaningful accessibility labels."], "completedWhen": "The store header displays the brand, navigation, and a cart count of zero.", "hint1": "Use header and nav elements to organize the navigation area.", "hint2": "Give the cart button and its count unique IDs for future JavaScript updates.", "solutionLanguage": "html", "solution": "<header class=\"store-header\">\n  <div class=\"header-inner\">\n\n    <a href=\"#store\" class=\"brand\">\n      <span>Tech</span>Store\n    </a>\n\n    <nav aria-label=\"Main navigation\">\n      <a href=\"#store\">Home</a>\n      <a href=\"#products\">Products</a>\n    </nav>\n\n    <button\n      id=\"cart-toggle\"\n      type=\"button\"\n      aria-controls=\"cart-panel\"\n      aria-expanded=\"false\"\n    >\n      Cart (<span id=\"cart-count\">0</span>)\n    </button>\n\n  </div>\n</header>", "check": "The navigation links and shopping cart button are visible. Cart interaction will be implemented later.", "image": null}, {"number": 3, "level": 1, "levelTitle": "Project Setup & HTML Structure", "title": "Create the product catalog and shopping cart structure", "why": "Dedicated containers allow JavaScript to update products, search results, cart items, and checkout information dynamically.", "workIn": "index.html. Replace the existing main element with the following structure. Keep the header from Mission 2.", "tasks": ["Create the store introduction section.", "Add a product search input.", "Create a category filter.", "Create a product grid container.", "Create the shopping cart section.", "Add subtotal, shipping, and total fields.", "Create checkout and close-cart buttons.", "Add a status message for user feedback."], "completedWhen": "All catalog and shopping cart elements exist in the HTML document.", "hint1": "JavaScript will later insert product cards inside an empty product grid.", "hint2": "Use unique IDs such as product-grid, cart-items, and cart-total.", "solutionLanguage": "html", "solution": "<main id=\"store\" class=\"store-container\">\n\n  <section class=\"store-hero\">\n    <p class=\"eyebrow\">TECH ESSENTIALS</p>\n    <h1>Explore Our Products</h1>\n    <p>Discover technology for your everyday needs.</p>\n  </section>\n\n  <section id=\"products\" aria-label=\"Product catalog\">\n\n    <div class=\"catalog-controls\">\n\n      <div>\n        <label for=\"search-input\">Search products</label>\n\n        <input\n          id=\"search-input\"\n          type=\"search\"\n          placeholder=\"Search products...\"\n        >\n      </div>\n\n      <div>\n        <label for=\"category-filter\">Category</label>\n\n        <select id=\"category-filter\">\n          <option value=\"all\">All categories</option>\n          <option value=\"Audio\">Audio</option>\n          <option value=\"Accessories\">Accessories</option>\n          <option value=\"Computing\">Computing</option>\n        </select>\n      </div>\n\n    </div>\n\n    <p id=\"product-count\" aria-live=\"polite\">\n      Products will appear here.\n    </p>\n\n    <div id=\"product-grid\"></div>\n\n  </section>\n\n  <aside\n    id=\"cart-panel\"\n    aria-labelledby=\"cart-title\"\n    hidden\n  >\n    <div class=\"cart-header\">\n      <h2 id=\"cart-title\">Shopping Cart</h2>\n\n      <button id=\"close-cart\" type=\"button\">\n        Close\n      </button>\n    </div>\n\n    <div id=\"cart-items\"></div>\n\n    <div class=\"cart-summary\">\n\n      <p>\n        Subtotal:\n        <strong id=\"cart-subtotal\">$0.00</strong>\n      </p>\n\n      <p>\n        Shipping:\n        <strong id=\"shipping-cost\">$0.00</strong>\n      </p>\n\n      <p class=\"total-line\">\n        Total:\n        <strong id=\"cart-total\">$0.00</strong>\n      </p>\n\n      <button id=\"checkout-button\" type=\"button\" disabled>\n        Checkout\n      </button>\n\n    </div>\n  </aside>\n\n  <p id=\"store-status\" role=\"status\"></p>\n\n</main>", "check": "The search input and category selector are visible. The cart panel is hidden until it is opened.", "image": null}, {"number": 4, "level": 2, "levelTitle": "CSS Styling & Responsive Design", "title": "Create the global styles and design system", "why": "Reusable colors and spacing rules create a consistent professional appearance throughout the store.", "workIn": "styles.css. Add the following global and header styles.", "tasks": ["Define reusable CSS color variables.", "Reset default browser spacing.", "Style the page background and typography.", "Create a consistent content container.", "Style the store header.", "Style the brand and navigation links.", "Add accessible keyboard focus styles."], "completedWhen": "The store displays a dark professional theme with blue and cyan accents.", "hint1": "Use CSS custom properties inside :root.", "hint2": "Use Flexbox to align the brand, navigation, and cart button.", "solutionLanguage": "css", "solution": ":root {\n  --background: #080d1e;\n  --surface: #151d34;\n  --primary: #0066ff;\n  --cyan: #22d3ee;\n  --text: #f8fafc;\n  --muted: #94a3b8;\n  --border: #334155;\n  --success: #22c55e;\n  --danger: #ef4444;\n}\n\n* {\n  box-sizing: border-box;\n}\n\n[hidden] {\n  display: none !important;\n}\n\nhtml {\n  scroll-behavior: smooth;\n}\n\nbody {\n  margin: 0;\n  background: var(--background);\n  color: var(--text);\n  font-family: Arial, sans-serif;\n  line-height: 1.6;\n}\n\na {\n  color: inherit;\n  text-decoration: none;\n}\n\nbutton,\ninput,\nselect {\n  font: inherit;\n}\n\nbutton {\n  cursor: pointer;\n}\n\nbutton:disabled {\n  cursor: not-allowed;\n  opacity: 0.5;\n}\n\n:focus-visible {\n  outline: 3px solid var(--cyan);\n  outline-offset: 3px;\n}\n\n.store-header {\n  position: sticky;\n  top: 0;\n  z-index: 10;\n  background: var(--surface);\n  border-bottom: 1px solid var(--border);\n}\n\n.header-inner {\n  max-width: 1200px;\n  margin: auto;\n  padding: 16px 24px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 20px;\n}\n\n.brand {\n  font-size: 24px;\n  font-weight: bold;\n}\n\n.brand span {\n  color: var(--cyan);\n}\n\nnav {\n  display: flex;\n  gap: 20px;\n}\n\nnav a:hover {\n  color: var(--cyan);\n}\n\n#cart-toggle {\n  border: 1px solid var(--cyan);\n  border-radius: 10px;\n  background: transparent;\n  color: var(--cyan);\n  padding: 8px 16px;\n}\n\n.store-container {\n  max-width: 1200px;\n  margin: auto;\n  padding: 32px 24px;\n}\n\n.store-hero {\n  padding: 30px 0;\n}\n\n.store-hero h1 {\n  font-size: clamp(28px, 5vw, 42px);\n  margin: 8px 0;\n}\n\n.store-hero p {\n  color: var(--muted);\n}\n\n.eyebrow {\n  color: var(--cyan) !important;\n  font-size: 12px;\n  font-weight: bold;\n  letter-spacing: 2px;\n}", "check": "The header and main content use consistent colors and spacing.", "image": null}, {"number": 5, "level": 2, "levelTitle": "CSS Styling & Responsive Design", "title": "Design the product cards and catalog layout", "why": "A responsive product grid helps customers browse products and compare prices efficiently.", "workIn": "styles.css. Append these catalog and product card styles below Mission 4.", "tasks": ["Style the search and filter controls.", "Create a responsive product grid.", "Design reusable product cards.", "Create a product illustration area.", "Style product names, categories, and prices.", "Design Add to Cart buttons.", "Add product card hover effects."], "completedWhen": "The stylesheet contains reusable product card styles ready for dynamic rendering.", "hint1": "Use CSS Grid with auto-fit to create flexible product columns.", "hint2": "Use repeat(auto-fit, minmax(...)) to adapt the grid to available space.", "solutionLanguage": "css", "solution": ".catalog-controls {\n  display: grid;\n  grid-template-columns: 2fr 1fr;\n  gap: 16px;\n  margin-bottom: 24px;\n}\n\n.catalog-controls label {\n  display: block;\n  color: var(--muted);\n  font-size: 13px;\n  margin-bottom: 6px;\n}\n\n.catalog-controls input,\n.catalog-controls select {\n  width: 100%;\n  padding: 12px;\n  color: var(--text);\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: 10px;\n  color-scheme: dark;\n}\n\n#product-count {\n  color: var(--muted);\n  font-size: 14px;\n}\n\n#product-grid {\n  display: grid;\n  grid-template-columns:\n    repeat(auto-fit, minmax(min(100%, 230px), 1fr));\n  gap: 20px;\n}\n\n.product-card {\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: 16px;\n  padding: 18px;\n  transition: border-color 0.2s, transform 0.2s;\n}\n\n.product-card:hover {\n  transform: translateY(-3px);\n  border-color: var(--cyan);\n}\n\n.product-icon {\n  display: grid;\n  place-items: center;\n  min-height: 130px;\n  background: var(--background);\n  border-radius: 12px;\n  font-size: 56px;\n}\n\n.product-category {\n  color: var(--cyan);\n  font-size: 12px;\n  margin-top: 12px;\n}\n\n.product-card h3 {\n  margin: 8px 0;\n  font-size: 17px;\n}\n\n.product-price {\n  margin-top: auto;\n  font-size: 22px;\n  font-weight: bold;\n}\n\n.add-to-cart,\n#checkout-button {\n  width: 100%;\n  border: none;\n  border-radius: 10px;\n  background: var(--primary);\n  color: white;\n  font-weight: bold;\n  padding: 12px;\n}\n\n.add-to-cart:hover,\n#checkout-button:hover:not(:disabled) {\n  background: #0052cc;\n}\n\n.empty-state {\n  grid-column: 1 / -1;\n  padding: 30px;\n  text-align: center;\n  color: var(--muted);\n}", "check": "The search and filter controls are styled. Product cards will become visible in Mission 8.", "image": null}, {"number": 6, "level": 2, "levelTitle": "CSS Styling & Responsive Design", "title": "Style the shopping cart and responsive layouts", "why": "Customers need a readable shopping cart and a store interface that works on different screen sizes.", "workIn": "styles.css. Append the cart and responsive styles.", "tasks": ["Create a fixed shopping cart panel.", "Style the cart header.", "Design cart item rows.", "Style quantity controls.", "Style the price summary.", "Add mobile media queries.", "Prevent horizontal overflow."], "completedWhen": "The cart styles are prepared and the catalog controls adapt to mobile screens.", "hint1": "Use position: fixed to display the cart above the main content.", "hint2": "Use a media query to stack the navigation and search controls on narrow screens.", "solutionLanguage": "css", "solution": "#cart-panel {\n  position: fixed;\n  top: 0;\n  right: 0;\n  bottom: 0;\n  z-index: 30;\n  width: min(420px, 100%);\n  overflow-y: auto;\n  background: var(--surface);\n  border-left: 1px solid var(--border);\n  padding: 24px;\n  box-shadow: -10px 0 40px rgba(0, 0, 0, 0.4);\n}\n\n.cart-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 12px;\n  border-bottom: 1px solid var(--border);\n  padding-bottom: 16px;\n}\n\n.cart-header h2 {\n  margin: 0;\n}\n\n#close-cart,\n.quantity-button,\n.remove-button {\n  background: transparent;\n  color: var(--text);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  padding: 6px 12px;\n}\n\n.cart-item {\n  padding: 16px 0;\n  border-bottom: 1px solid var(--border);\n}\n\n.cart-item h3 {\n  margin: 0 0 6px;\n  font-size: 16px;\n}\n\n.cart-item-price {\n  color: var(--cyan);\n  font-weight: bold;\n}\n\n.quantity-controls {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 10px;\n  margin-top: 12px;\n}\n\n.remove-button {\n  color: #fca5a5;\n}\n\n.cart-summary {\n  margin-top: 24px;\n  padding: 18px;\n  background: var(--background);\n  border-radius: 12px;\n}\n\n.cart-summary p {\n  display: flex;\n  justify-content: space-between;\n  gap: 12px;\n}\n\n.total-line {\n  border-top: 1px solid var(--border);\n  padding-top: 12px;\n  color: var(--cyan);\n  font-size: 20px;\n}\n\n#store-status {\n  color: var(--cyan);\n  font-size: 14px;\n}\n\n@media (max-width: 600px) {\n  .header-inner {\n    flex-wrap: wrap;\n    gap: 12px;\n    padding: 12px 16px;\n  }\n\n  nav {\n    order: 3;\n    width: 100%;\n    justify-content: center;\n  }\n\n  .store-container {\n    padding: 20px 16px;\n  }\n\n  .catalog-controls {\n    grid-template-columns: 1fr;\n  }\n\n  #cart-panel {\n    padding: 16px;\n  }\n}", "check": "At mobile widths, the search and category controls stack vertically and no horizontal scrolling is needed.", "image": null}, {"number": 7, "level": 3, "levelTitle": "Dynamic Products, Search & Filtering", "title": "Create the product data array", "why": "Separating product data from HTML allows the application to generate and manage products efficiently.", "workIn": "script.js. Create the product data array and currency formatting function.", "tasks": ["Create an array named products.", "Represent products as JavaScript objects.", "Assign each product a unique ID.", "Add names and categories.", "Store prices as numbers.", "Add product illustration icons.", "Create six different products.", "Create a reusable currency formatting function."], "completedWhen": "The products array contains six valid objects with unique IDs.", "hint1": "Use the same property names for every product object.", "hint2": "Store prices in cents as integers to avoid floating-point rounding problems.", "solutionLanguage": "javascript", "solution": "const products = [\n  {\n    id: 1,\n    name: \"Wireless Headphones\",\n    category: \"Audio\",\n    price: 5900,\n    icon: \"🎧\"\n  },\n  {\n    id: 2,\n    name: \"Smart Watch\",\n    category: \"Accessories\",\n    price: 7900,\n    icon: \"⌚\"\n  },\n  {\n    id: 3,\n    name: \"Mechanical Keyboard\",\n    category: \"Computing\",\n    price: 8900,\n    icon: \"⌨️\"\n  },\n  {\n    id: 4,\n    name: \"Bluetooth Speaker\",\n    category: \"Audio\",\n    price: 4500,\n    icon: \"🔊\"\n  },\n  {\n    id: 5,\n    name: \"Wireless Mouse\",\n    category: \"Computing\",\n    price: 2900,\n    icon: \"🖱️\"\n  },\n  {\n    id: 6,\n    name: \"Portable Charger\",\n    category: \"Accessories\",\n    price: 3900,\n    icon: \"🔋\"\n  }\n];\n\nfunction formatPrice(cents) {\n  return new Intl.NumberFormat(\"en-US\", {\n    style: \"currency\",\n    currency: \"USD\"\n  }).format(cents / 100);\n}", "check": "Typing products.length in the browser console returns 6, and formatPrice(5900) returns $59.00.", "image": null}, {"number": 8, "level": 3, "levelTitle": "Dynamic Products, Search & Filtering", "title": "Render product cards dynamically", "why": "Dynamic rendering makes the interface automatically reflect the product data instead of requiring manually written HTML cards.", "workIn": "script.js. Append the rendering function below the product data.", "tasks": ["Select the product grid container.", "Select the product count element.", "Create a renderProducts function.", "Clear previously rendered products.", "Create a product card for each object.", "Display product information and price.", "Add a product ID to each Add to Cart button.", "Render the initial product list."], "completedWhen": "All six products appear in the catalog with their names, categories, prices, and buttons.", "hint1": "Use forEach to process every product in the array.", "hint2": "Use document.createElement and textContent to construct product elements.", "solutionLanguage": "javascript", "solution": "const productGrid =\n  document.getElementById(\"product-grid\");\n\nconst productCount =\n  document.getElementById(\"product-count\");\n\nfunction createTextElement(tag, text, className) {\n  const element = document.createElement(tag);\n\n  element.textContent = text;\n\n  if (className) {\n    element.className = className;\n  }\n\n  return element;\n}\n\nfunction renderProducts(items) {\n  productGrid.innerHTML = \"\";\n\n  productCount.textContent =\n    items.length + \" products found\";\n\n  if (items.length === 0) {\n    productGrid.appendChild(\n      createTextElement(\n        \"p\",\n        \"No products found.\",\n        \"empty-state\"\n      )\n    );\n\n    return;\n  }\n\n  items.forEach((product) => {\n    const card = document.createElement(\"article\");\n\n    card.className = \"product-card\";\n\n    const icon = createTextElement(\n      \"div\",\n      product.icon,\n      \"product-icon\"\n    );\n\n    icon.setAttribute(\"aria-hidden\", \"true\");\n\n    const category = createTextElement(\n      \"p\",\n      product.category,\n      \"product-category\"\n    );\n\n    const name = createTextElement(\n      \"h3\",\n      product.name\n    );\n\n    const price = createTextElement(\n      \"p\",\n      formatPrice(product.price),\n      \"product-price\"\n    );\n\n    const button = createTextElement(\n      \"button\",\n      \"Add to Cart\",\n      \"add-to-cart\"\n    );\n\n    button.type = \"button\";\n    button.dataset.id = product.id;\n\n    button.setAttribute(\n      \"aria-label\",\n      \"Add \" + product.name + \" to cart\"\n    );\n\n    card.append(icon, category, name, price, button);\n\n    productGrid.appendChild(card);\n  });\n}\n\nrenderProducts(products);", "check": "Six product cards appear. Add to Cart buttons are visible but will become functional in Mission 10.", "image": "/projects/ecommerce-frontend/mission-08.png"}, {"number": 9, "level": 3, "levelTitle": "Dynamic Products, Search & Filtering", "title": "Implement product search and category filtering", "why": "Search and filtering help customers find relevant products without browsing the complete catalog.", "workIn": "script.js. Append the search and filtering logic.", "tasks": ["Select the search input.", "Select the category dropdown.", "Read the current search value.", "Convert search text to lowercase.", "Filter products by name.", "Filter products by category.", "Combine both filtering conditions.", "Render the filtered products.", "Display an empty state when no products match."], "completedWhen": "Search and category filters update the product grid immediately.", "hint1": "Use the filter method to create a new array without modifying the original products array.", "hint2": "Combine name matching and category matching using the logical AND operator.", "solutionLanguage": "javascript", "solution": "const searchInput =\n  document.getElementById(\"search-input\");\n\nconst categoryFilter =\n  document.getElementById(\"category-filter\");\n\nfunction filterProducts() {\n  const search =\n    searchInput.value.trim().toLowerCase();\n\n  const category = categoryFilter.value;\n\n  const filteredProducts = products.filter((product) => {\n    const matchesSearch =\n      product.name.toLowerCase().includes(search);\n\n    const matchesCategory =\n      category === \"all\" ||\n      product.category === category;\n\n    return matchesSearch && matchesCategory;\n  });\n\n  renderProducts(filteredProducts);\n}\n\nsearchInput.addEventListener(\n  \"input\",\n  filterProducts\n);\n\ncategoryFilter.addEventListener(\n  \"change\",\n  filterProducts\n);", "check": "Searching for Wireless displays matching products. Selecting Audio displays only Audio products when the search input is empty.", "image": "/projects/ecommerce-frontend/mission-09.png"}, {"number": 10, "level": 4, "levelTitle": "Shopping Cart & Price Calculation", "title": "Implement Add to Cart functionality", "why": "The shopping cart must track selected products and combine repeated additions into quantities.", "workIn": "script.js. Append the shopping cart state, rendering, and event handling code.", "tasks": ["Create an empty cart array.", "Select the shopping cart elements.", "Identify products using their IDs.", "Check whether a product already exists in the cart.", "Increase its quantity if it already exists.", "Add a new cart item if needed.", "Display selected products in the cart.", "Update the cart count.", "Implement opening and closing the cart."], "completedWhen": "Adding products updates the shopping cart and its quantity indicator.", "hint1": "Use find to locate an existing cart item.", "hint2": "Store only the product ID and quantity in each cart object.", "solutionLanguage": "javascript", "solution": "let cart = [];\n\nconst MAX_QUANTITY = 99;\n\nconst cartPanel =\n  document.getElementById(\"cart-panel\");\n\nconst cartToggle =\n  document.getElementById(\"cart-toggle\");\n\nconst closeCartButton =\n  document.getElementById(\"close-cart\");\n\nconst cartCount =\n  document.getElementById(\"cart-count\");\n\nconst cartItems =\n  document.getElementById(\"cart-items\");\n\nconst storeStatus =\n  document.getElementById(\"store-status\");\n\nfunction renderCart() {\n  cartItems.innerHTML = \"\";\n\n  cartCount.textContent = cart.reduce(\n    (total, item) => total + item.quantity,\n    0\n  );\n\n  cart.forEach((item) => {\n    const product = products.find(\n      (product) => product.id === item.id\n    );\n\n    const row = document.createElement(\"article\");\n\n    row.className = \"cart-item\";\n\n    row.append(\n      createTextElement(\"h3\", product.name),\n      createTextElement(\n        \"p\",\n        \"Quantity: \" + item.quantity\n      )\n    );\n\n    cartItems.appendChild(row);\n  });\n}\n\nfunction addToCart(productId) {\n  const product = products.find(\n    (item) => item.id === productId\n  );\n\n  if (!product) return;\n\n  const existingItem = cart.find(\n    (item) => item.id === productId\n  );\n\n  if (existingItem) {\n    if (existingItem.quantity >= MAX_QUANTITY) {\n      storeStatus.textContent =\n        \"Maximum quantity reached.\";\n\n      return;\n    }\n\n    existingItem.quantity += 1;\n  } else {\n    cart.push({\n      id: productId,\n      quantity: 1\n    });\n  }\n\n  renderCart();\n\n  storeStatus.textContent =\n    product.name + \" added to cart.\";\n}\n\nproductGrid.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\".add-to-cart\");\n\n  if (!button) return;\n\n  addToCart(Number(button.dataset.id));\n});\n\nfunction openCart() {\n  cartPanel.hidden = false;\n  cartToggle.setAttribute(\"aria-expanded\", \"true\");\n  closeCartButton.focus();\n}\n\nfunction closeCart() {\n  cartPanel.hidden = true;\n  cartToggle.setAttribute(\"aria-expanded\", \"false\");\n  cartToggle.focus();\n}\n\ncartToggle.addEventListener(\"click\", openCart);\n\ncloseCartButton.addEventListener(\"click\", closeCart);\n\ndocument.addEventListener(\"keydown\", (event) => {\n  if (event.key === \"Escape\" && !cartPanel.hidden) {\n    closeCart();\n  }\n});\n\nrenderCart();", "check": "Adding the same product twice displays a quantity of two and increases the cart count correctly.", "image": "/projects/ecommerce-frontend/mission-10.png"}, {"number": 11, "level": 4, "levelTitle": "Shopping Cart & Price Calculation", "title": "Update quantities and remove products", "why": "Customers must be able to change quantities and remove unwanted products before checkout.", "workIn": "script.js. Replace only the existing renderCart function with the version below. Append the quantity and removal functions after the existing code.", "tasks": ["Display increase and decrease quantity buttons.", "Create a remove product button.", "Identify cart items using product IDs.", "Update product quantities.", "Prevent quantities above the maximum.", "Remove products when quantity reaches zero.", "Update the cart after every change."], "completedWhen": "The cart supports increasing, decreasing, and removing products.", "hint1": "Use filter to remove an item from the cart array.", "hint2": "Use a data-action attribute to distinguish increase, decrease, and remove buttons.", "solutionLanguage": "javascript", "solution": "// Replace the existing renderCart function.\n\nfunction renderCart() {\n  cartItems.innerHTML = \"\";\n\n  cartCount.textContent = cart.reduce(\n    (total, item) => total + item.quantity,\n    0\n  );\n\n  cart.forEach((item) => {\n    const product = products.find(\n      (product) => product.id === item.id\n    );\n\n    const row = document.createElement(\"article\");\n\n    row.className = \"cart-item\";\n\n    const name = createTextElement(\n      \"h3\",\n      product.name\n    );\n\n    const price = createTextElement(\n      \"p\",\n      formatPrice(product.price),\n      \"cart-item-price\"\n    );\n\n    const controls = document.createElement(\"div\");\n\n    controls.className = \"quantity-controls\";\n\n    const decrease = createCartButton(\n      \"-\",\n      \"decrease\",\n      item.id,\n      \"quantity-button\"\n    );\n\n    const quantity = createTextElement(\n      \"span\",\n      String(item.quantity)\n    );\n\n    const increase = createCartButton(\n      \"+\",\n      \"increase\",\n      item.id,\n      \"quantity-button\"\n    );\n\n    increase.disabled =\n      item.quantity >= MAX_QUANTITY;\n\n    const remove = createCartButton(\n      \"Remove\",\n      \"remove\",\n      item.id,\n      \"remove-button\"\n    );\n\n    controls.append(\n      decrease,\n      quantity,\n      increase,\n      remove\n    );\n\n    row.append(name, price, controls);\n\n    cartItems.appendChild(row);\n  });\n}\n\n// Append the following functions.\n\nfunction createCartButton(text, action, id, className) {\n  const button = createTextElement(\n    \"button\",\n    text,\n    className\n  );\n\n  button.type = \"button\";\n  button.dataset.action = action;\n  button.dataset.id = id;\n\n  const product = products.find(\n    (item) => item.id === id\n  );\n\n  button.setAttribute(\n    \"aria-label\",\n    action + \" \" + product.name\n  );\n\n  return button;\n}\n\nfunction changeQuantity(id, amount) {\n  const item = cart.find(\n    (item) => item.id === id\n  );\n\n  if (!item) return;\n\n  item.quantity = Math.min(\n    MAX_QUANTITY,\n    item.quantity + amount\n  );\n\n  if (item.quantity <= 0) {\n    removeFromCart(id);\n    return;\n  }\n\n  renderCart();\n}\n\nfunction removeFromCart(id) {\n  cart = cart.filter(\n    (item) => item.id !== id\n  );\n\n  renderCart();\n}\n\ncartItems.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\n    \"button[data-action]\"\n  );\n\n  if (!button) return;\n\n  const id = Number(button.dataset.id);\n  const action = button.dataset.action;\n\n  if (action === \"increase\") {\n    changeQuantity(id, 1);\n  } else if (action === \"decrease\") {\n    changeQuantity(id, -1);\n  } else if (action === \"remove\") {\n    removeFromCart(id);\n  }\n});", "check": "Increasing and decreasing quantities works. Removing an item updates the cart count, and quantities cannot become negative.", "image": "/projects/ecommerce-frontend/mission-11.png"}, {"number": 12, "level": 4, "levelTitle": "Shopping Cart & Price Calculation", "title": "Calculate cart totals and update the interface", "why": "Accurate price calculations are essential for a reliable shopping cart.", "workIn": "script.js. Append the total calculation code. Add updateCartTotals() at the end of renderCart, after its forEach block. Keep the final renderCart call below the new declarations.", "tasks": ["Select the subtotal element.", "Select the shipping cost element.", "Select the final total element.", "Calculate price multiplied by quantity.", "Sum the prices of all cart items.", "Apply a five-dollar shipping fee to non-empty carts.", "Update the displayed totals.", "Disable checkout when the cart is empty."], "completedWhen": "Subtotal, shipping, and total values update whenever the cart changes.", "hint1": "Use reduce to calculate the sum of product prices multiplied by their quantities.", "hint2": "All prices are stored in cents, so five dollars is represented by 500.", "solutionLanguage": "javascript", "solution": "const subtotalElement =\n  document.getElementById(\"cart-subtotal\");\n\nconst shippingElement =\n  document.getElementById(\"shipping-cost\");\n\nconst totalElement =\n  document.getElementById(\"cart-total\");\n\nconst checkoutButton =\n  document.getElementById(\"checkout-button\");\n\nfunction calculateTotals() {\n  const subtotal = cart.reduce((total, item) => {\n    const product = products.find(\n      (product) => product.id === item.id\n    );\n\n    return total + product.price * item.quantity;\n  }, 0);\n\n  const shipping = cart.length > 0 ? 500 : 0;\n\n  return {\n    subtotal: subtotal,\n    shipping: shipping,\n    total: subtotal + shipping\n  };\n}\n\nfunction updateCartTotals() {\n  const totals = calculateTotals();\n\n  subtotalElement.textContent =\n    formatPrice(totals.subtotal);\n\n  shippingElement.textContent =\n    formatPrice(totals.shipping);\n\n  totalElement.textContent =\n    formatPrice(totals.total);\n\n  checkoutButton.disabled = cart.length === 0;\n}\n\n// Add updateCartTotals() at the end of\n// the existing renderCart function.\n//\n// Move the initial renderCart() call to\n// the bottom of script.js, after all\n// declarations above have been initialized.", "check": "Two headphones priced at $59 each produce a subtotal of $118.00, shipping of $5.00, and a total of $123.00.", "image": "/projects/ecommerce-frontend/mission-12.png"}, {"number": 13, "level": 5, "levelTitle": "Local Storage & Final Testing", "title": "Save and restore cart data using Local Storage", "why": "Local Storage allows the shopping cart to survive a browser refresh without requiring a backend database.", "workIn": "script.js. Append the storage functions. Add saveCart() at the end of renderCart, after updateCartTotals(). Replace the initial renderCart() call with the initialization shown below.", "tasks": ["Choose a unique Local Storage key.", "Convert the cart array into JSON.", "Save cart data after changes.", "Read the saved cart when the page loads.", "Convert JSON back into JavaScript data.", "Validate saved product IDs and quantities.", "Handle missing or invalid storage data.", "Verify persistence after refreshing."], "completedWhen": "The shopping cart retains valid products and quantities after a browser refresh.", "hint1": "Local Storage stores strings, not JavaScript arrays directly.", "hint2": "Use JSON.stringify to save the array and JSON.parse to restore it.", "solutionLanguage": "javascript", "solution": "const CART_STORAGE_KEY = \"techstore-cart\";\n\nfunction saveCart() {\n  try {\n    localStorage.setItem(\n      CART_STORAGE_KEY,\n      JSON.stringify(cart)\n    );\n  } catch {\n    storeStatus.textContent =\n      \"Cart storage is unavailable.\";\n  }\n}\n\nfunction loadCart() {\n  try {\n    const savedCart =\n      localStorage.getItem(CART_STORAGE_KEY);\n\n    if (!savedCart) return [];\n\n    const parsedCart = JSON.parse(savedCart);\n\n    if (!Array.isArray(parsedCart)) {\n      return [];\n    }\n\n    const validCart = [];\n\n    parsedCart.forEach((item) => {\n      if (\n        !item ||\n        !products.some(\n          (product) => product.id === item.id\n        ) ||\n        !Number.isInteger(item.quantity) ||\n        item.quantity <= 0\n      ) {\n        return;\n      }\n\n      const existing = validCart.find(\n        (entry) => entry.id === item.id\n      );\n\n      if (existing) {\n        existing.quantity = Math.min(\n          MAX_QUANTITY,\n          existing.quantity + item.quantity\n        );\n      } else {\n        validCart.push({\n          id: item.id,\n          quantity: Math.min(\n            MAX_QUANTITY,\n            item.quantity\n          )\n        });\n      }\n    });\n\n    return validCart;\n\n  } catch {\n    return [];\n  }\n}\n\n// Add saveCart() at the end of renderCart.\n//\n// Remove the previous standalone renderCart()\n// initialization and replace it with these\n// two lines at the bottom of script.js:\n\ncart = loadCart();\nrenderCart();", "check": "Add products, refresh the page, and verify that quantities and totals are restored correctly. Test using a local HTTP server for reliable storage behavior.", "image": "/projects/ecommerce-frontend/mission-13.png"}, {"number": 14, "level": 5, "levelTitle": "Local Storage & Final Testing", "title": "Implement checkout summary and empty cart states", "why": "A complete shopping experience needs clear feedback when the cart is empty and when checkout is simulated.", "workIn": "script.js. Append the empty state and checkout functions before the final initialization. Add renderEmptyCartState() inside renderCart after the product rendering loop.", "tasks": ["Display a message when the cart is empty.", "Keep checkout disabled for an empty cart.", "Calculate the final order total.", "Create a simulated checkout confirmation.", "Allow the customer to cancel checkout.", "Clear the cart after confirmation.", "Update Local Storage and cart totals.", "Display a successful demo checkout message."], "completedWhen": "The application can simulate checkout, clear the cart, and display a meaningful empty cart message.", "hint1": "Check whether cart.length equals zero before processing checkout.", "hint2": "Clearing the cart and calling renderCart updates both the interface and saved cart data.", "solutionLanguage": "javascript", "solution": "function renderEmptyCartState() {\n  if (cart.length === 0) {\n    cartItems.appendChild(\n      createTextElement(\n        \"p\",\n        \"Your cart is empty.\",\n        \"empty-state\"\n      )\n    );\n  }\n}\n\nfunction checkout() {\n  if (cart.length === 0) return;\n\n  const totals = calculateTotals();\n\n  const itemCount = cart.reduce(\n    (total, item) => total + item.quantity,\n    0\n  );\n\n  const confirmed = window.confirm(\n    \"Demo checkout only. \" +\n    itemCount + \" item(s). \" +\n    \"Total: \" + formatPrice(totals.total) +\n    \". Confirm?\"\n  );\n\n  if (!confirmed) return;\n\n  cart = [];\n\n  renderCart();\n  closeCart();\n\n  storeStatus.textContent =\n    \"Demo checkout completed successfully. \" +\n    \"No payment was processed.\";\n}\n\ncheckoutButton.addEventListener(\n  \"click\",\n  checkout\n);\n\n// Add renderEmptyCartState() inside renderCart\n// after the product rendering loop.\n//\n// Keep updateCartTotals() and saveCart()\n// at the end of renderCart.\n//\n// Keep cart = loadCart() and renderCart()\n// as the final initialization statements.", "check": "Checkout displays a confirmation. Cancelling preserves the cart. Confirming clears the cart and displays a demo success message without processing payments.", "image": "/projects/ecommerce-frontend/mission-14.png"}, {"number": 15, "level": 5, "levelTitle": "Local Storage & Final Testing", "title": "Test and improve the complete application", "why": "Systematic testing ensures the store behaves correctly during normal interactions and unexpected user actions.", "workIn": "index.html, styles.css, script.js, and browser Developer Tools.", "tasks": ["Verify that all six products appear.", "Test search with uppercase and lowercase letters.", "Test each category filter.", "Test combined search and category filtering.", "Verify the no-products-found state.", "Add different products to the cart.", "Add the same product multiple times.", "Test increasing and decreasing quantities.", "Verify the maximum quantity limit.", "Test removing products.", "Verify subtotal, shipping, and final total.", "Refresh and verify Local Storage persistence.", "Test checkout confirmation and cancellation.", "Test the empty cart state.", "Test desktop and mobile layouts.", "Test keyboard navigation and Escape.", "Check the browser console for errors."], "completedWhen": "The complete store passes functional, persistence, accessibility, and responsive layout tests.", "hint1": "Test both normal behavior and edge cases, such as empty carts and search results.", "hint2": "Use the browser console, responsive device toolbar, and Application Storage panel.", "solutionLanguage": "javascript", "solution": "// Optional development checks.\n// Run these in the browser console.\n\nconsole.assert(\n  products.length === 6,\n  \"The catalog should contain six products.\"\n);\n\nconsole.assert(\n  new Set(\n    products.map((product) => product.id)\n  ).size === products.length,\n  \"Product IDs must be unique.\"\n);\n\nconsole.assert(\n  products.every((product) =>\n    Number.isInteger(product.price) &&\n    product.price > 0\n  ),\n  \"Product prices must be positive integers.\"\n);\n\nconsole.assert(\n  formatPrice(5900) === \"$59.00\",\n  \"Currency formatting must be correct.\"\n);\n\nconsole.assert(\n  cart.every((item) =>\n    products.some(\n      (product) => product.id === item.id\n    ) &&\n    Number.isInteger(item.quantity) &&\n    item.quantity > 0 &&\n    item.quantity <= MAX_QUANTITY\n  ),\n  \"Cart items must contain valid data.\"\n);\n\nconst totals = calculateTotals();\n\nconsole.assert(\n  totals.total ===\n    totals.subtotal + totals.shipping,\n  \"The total calculation must be correct.\"\n);\n\n// Manual test example:\n// Add two headphones and one wireless mouse.\n//\n// Expected subtotal: $147.00\n// Expected shipping: $5.00\n// Expected total: $152.00\n//\n// Refresh and verify that the cart is preserved.\n// Cancel checkout and verify that nothing changes.\n// Confirm demo checkout and verify an empty cart.", "check": "All manual tests pass, prices remain accurate, cart persistence works, and the console displays no unexpected errors.", "image": null}], "questions": [{"id": 1, "question": "A customer searches for Wireless and selects the Audio category. How should the application filter the products?", "options": ["Display every product containing Wireless, regardless of its category", "Display every Audio product, regardless of its name", "Display only products matching both the search text and the selected category", "Remove all non-matching products permanently from the original array"], "correct": 2, "explanation": "The search and category conditions must be combined using the logical AND operator. The filter method returns matching products without modifying the original products array."}, {"id": 2, "question": "The cart contains two headphones priced at 5900 cents each and one wireless mouse priced at 2900 cents. Shipping costs 500 cents. Which calculation produces the correct total?", "options": ["(5900 * 2 + 2900 + 500) / 100 = $152.00", "(5900 + 2900 + 500) / 100 = $93.00", "(5900 * 2 + 2900) / 100 = $147.00", "(5900 * 2 + 2900 + 500) = $15,200.00"], "correct": 0, "explanation": "Multiply each product price by its quantity, sum all item costs, and add shipping once. Divide the final amount in cents by 100 to display dollars. Integer cents help avoid floating-point precision problems."}, {"id": 3, "question": "After refreshing the store, how should the application safely restore the shopping cart from Local Storage?", "options": ["Read the stored string and use it directly as a cart array", "Create an empty cart and immediately overwrite the saved data", "Restore the previous HTML without restoring the JavaScript cart state", "Parse the saved JSON, validate product IDs and quantities, restore the cart state, and render the interface"], "correct": 3, "explanation": "Local Storage stores strings. JSON.parse restores the saved data, which must be validated before use. Updating the cart state and calling renderCart restores the interface, quantities, and calculated totals."}]}]$guided_seed$::jsonb) LOOP
    SELECT projects.id INTO STRICT pr_id
    FROM public.projects
    JOIN public.technologies ON technologies.id=projects.technology_id
    WHERE technologies.slug='html-css-js' AND projects.slug=p->>'slug';

    IF EXISTS(SELECT 1 FROM public.levels WHERE project_id=pr_id)
       OR EXISTS(SELECT 1 FROM public.assessments WHERE project_id=pr_id) THEN
      RAISE EXCEPTION 'Learning path or assessment exists for %, refusing overwrite',p->>'slug';
    END IF;

    FOR lev IN SELECT value FROM jsonb_array_elements(p->'levels') LOOP
      INSERT INTO public.levels(project_id,level_number,title,description,objective,given_items)
      VALUES(pr_id,(lev->>'number')::integer,lev->>'name',lev->>'goal',lev->>'goal',
        ARRAY(SELECT jsonb_array_elements_text(lev->'given')))
      RETURNING id INTO lev_id;

      n:=0;
      FOR mis IN SELECT value FROM jsonb_array_elements(p->'missions')
                 WHERE (value->>'level')::integer=(lev->>'number')::integer
                 ORDER BY (value->>'number')::integer LOOP
        n:=n+1;
        INSERT INTO public.missions(
          level_id,mission_number,title,summary,instructions,purpose,file_to_edit,
          expected_result,expected_image_path,hint_1,hint_2,final_answer,
          solution_language,success_criteria,verification_check
        ) VALUES (
          lev_id,(mis->>'number')::integer,mis->>'title',mis->>'why',mis->>'workIn',
          mis->>'why',mis->>'workIn',mis->>'completedWhen',mis->>'image',
          mis->>'hint1',mis->>'hint2',mis->>'solution',mis->>'solutionLanguage',
          mis->>'completedWhen',mis->>'check'
        ) RETURNING id INTO mis_id;
        INSERT INTO public.mission_tasks(mission_id,task_number,instruction)
        SELECT mis_id, ordinality::integer, value #>> '{}'
        FROM jsonb_array_elements(mis->'tasks') WITH ORDINALITY AS items(value,ordinality);
      END LOOP;
    END LOOP;

    INSERT INTO public.assessments(project_id,title)
    VALUES(pr_id, CASE p->>'slug' WHEN 'quiz-application' THEN 'Quiz Application - Final Assessment'
                                 ELSE 'E-commerce Frontend - Final Assessment' END)
    RETURNING id INTO assess_id;
    n:=0;
    FOR question IN SELECT value FROM jsonb_array_elements(p->'questions') LOOP
      n:=n+1;
      INSERT INTO public.assessment_questions(assessment_id,question_number,question_text)
      VALUES(assess_id,n,question->>'question') RETURNING id INTO question_id;
      INSERT INTO public.assessment_options(question_id,option_number,option_text,is_correct)
      SELECT question_id, ordinality::integer, value #>> '{}',
             (ordinality-1)=(question->>'correct')::integer
      FROM jsonb_array_elements(question->'options') WITH ORDINALITY AS opts(value,ordinality);
    END LOOP;

    SELECT count(*) INTO count_levels FROM public.levels WHERE project_id=pr_id;
    SELECT count(*) INTO count_missions FROM public.missions m JOIN public.levels l ON l.id=m.level_id WHERE l.project_id=pr_id;
    SELECT count(*) INTO count_tasks FROM public.mission_tasks mt JOIN public.missions m ON m.id=mt.mission_id JOIN public.levels l ON l.id=m.level_id WHERE l.project_id=pr_id;
    IF count_levels <> jsonb_array_length(p->'levels') OR count_missions <> jsonb_array_length(p->'missions')
      OR count_tasks <> (SELECT sum(jsonb_array_length(value->'tasks'))::integer FROM jsonb_array_elements(p->'missions')) THEN
      RAISE EXCEPTION 'Seed validation failed for %',p->>'slug';
    END IF;
    IF (SELECT count(*) FROM public.assessment_questions WHERE assessment_id=assess_id)<>3
      OR (SELECT count(*) FROM public.assessment_options o JOIN public.assessment_questions q ON q.id=o.question_id WHERE q.assessment_id=assess_id)<>12 THEN
      RAISE EXCEPTION 'Assessment validation failed for %',p->>'slug';
    END IF;
  END LOOP;
END;
$seed$;

-- Secure grading: the authenticated learner cannot read the answer key or
-- fabricate assessment_progress rows. Original Portfolio RPC stays unchanged.
CREATE OR REPLACE FUNCTION public.submit_guided_assessment(p_project_slug text,p_option_ids bigint[])
RETURNS TABLE(correct_answers integer,total_questions integer,already_completed boolean)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $func$
DECLARE
  uid uuid:=auth.uid();
  pid bigint;
  aid bigint;
  total integer;
  matched integer;
  unique_questions integer;
  score integer;
  old_correct integer;
  old_total integer;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
  IF p_project_slug NOT IN ('quiz-application','ecommerce-frontend') OR p_project_slug IS NULL THEN
    RAISE EXCEPTION 'Unsupported project';
  END IF;
  SELECT p.id,a.id INTO pid,aid
  FROM public.projects p JOIN public.technologies tech ON tech.id=p.technology_id
  JOIN public.assessments a ON a.project_id=p.id
  WHERE p.slug=p_project_slug AND tech.slug='html-css-js';
  IF aid IS NULL THEN RAISE EXCEPTION 'Assessment unavailable'; END IF;
  SELECT count(*) INTO total FROM public.assessment_questions WHERE assessment_id=aid;
  IF total<>3 THEN RAISE EXCEPTION 'Assessment configuration invalid'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.missions m JOIN public.levels l ON l.id=m.level_id WHERE l.project_id=pid)
    OR EXISTS(
      SELECT 1 FROM public.missions m JOIN public.levels l ON l.id=m.level_id
      WHERE l.project_id=pid AND NOT EXISTS(
        SELECT 1 FROM public.mission_progress mp WHERE mp.mission_id=m.id AND mp.user_id=uid
      )
    ) THEN RAISE EXCEPTION 'Complete all missions before submitting'; END IF;

  SELECT ap.correct_answers,ap.total_questions INTO old_correct,old_total
  FROM public.assessment_progress ap WHERE ap.user_id=uid AND ap.assessment_id=aid;
  IF FOUND THEN
    IF old_correct IS NULL OR old_total IS NULL THEN RAISE EXCEPTION 'Existing result needs review'; END IF;
    RETURN QUERY SELECT old_correct,old_total,true;
    RETURN;
  END IF;

  IF p_option_ids IS NULL OR cardinality(p_option_ids)<>total THEN
    RAISE EXCEPTION 'Answer every question';
  END IF;
  SELECT count(*),count(distinct q.id),count(*) FILTER(WHERE o.is_correct)
  INTO matched,unique_questions,score
  FROM unnest(p_option_ids) AS s(option_id)
  JOIN public.assessment_options o ON o.id=s.option_id
  JOIN public.assessment_questions q ON q.id=o.question_id
  WHERE q.assessment_id=aid;
  IF matched<>total OR unique_questions<>total THEN RAISE EXCEPTION 'Invalid answers'; END IF;

  INSERT INTO public.assessment_progress(user_id,assessment_id,correct_answers,total_questions)
  VALUES(uid,aid,score,total)
  ON CONFLICT(user_id,assessment_id) DO NOTHING;
  SELECT ap.correct_answers,ap.total_questions INTO old_correct,old_total
  FROM public.assessment_progress ap WHERE ap.user_id=uid AND ap.assessment_id=aid;
  IF old_correct IS NULL THEN RAISE EXCEPTION 'Could not save result'; END IF;
  RETURN QUERY SELECT old_correct,old_total,(old_correct<>score);
END;
$func$;
REVOKE ALL ON FUNCTION public.submit_guided_assessment(text,bigint[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.submit_guided_assessment(text,bigint[]) TO authenticated;
COMMIT;
